const embodiedBridgeFrame = (observation: OrganismObservation, tick: number, fallback: number[]) => {
    const pick = (values: number[] | undefined) => Array.isArray(values) ? values.slice(0, 16).map(v => Math.max(-1, Math.min(1, Number.isFinite(Number(v)) ? Number(v) : 0))) : [];
    const vision = pick(observation.vision?.features?.length ? observation.vision.features : observation.vision?.rawRgb);
    const audio = pick(observation.audio?.samples);
    const inter = [
        observation.embodiment?.bodyEnergy01 ?? .7,
        observation.embodiment?.cognitiveCapacity01 ?? .7,
        observation.embodiment?.thermalStrain01 ?? .2,
        observation.embodiment?.sensoryFreshness01 ?? .8,
        observation.embodiment?.battery01 ?? .8,
        observation.embodiment?.cpuLoad01 ?? .25,
        observation.embodiment?.ramPressure01 ?? .2,
        observation.embodiment?.awake === false ? 0 : 1,
    ];
    const world = observation.worldContext ?
        [Number(observation.worldContext.objects?.length ?? 0) / 16, Number(observation.worldContext.uncertainty ?? .5), Number(observation.worldContext.attention ?? .5), Number(observation.worldContext.energy ?? .7)] : [];
    const social = [observation.socialSignal ?? .0, observation.novelty ?? .2, Number(observation.surprise ?? .0), Number(observation.reward ?? .5)];
    const context = [Number(observation.success ?? .5), Number(observation.externalGoal?.importance ?? 0), Number(observation.externalGoal?.urgency ?? 0), fallback[0] ?? .5, fallback[1] ?? 0];
    const features = [...vision, ...audio, ...inter, ...world, ...social, ...context, ...fallback].slice(0, 64);
    while (features.length < 64)
        features.push(0);
    const mk = (values: number[], fresh: number, confidence: number, source: string) => ({ tick, values: values.slice(0, 16), freshness01: clamp(fresh), confidence01: clamp(confidence), ageTicks: 0, source });
    return { sensorFeatures: features, sensors: { vision: mk(vision, observation.embodiment?.sensoryFreshness01 ?? .8, observation.vision?.confidence01 ?? .65, 'vision'), audio: mk(audio, .72, observation.audio?.confidence01 ?? .55, 'audio'), interoception: mk(inter, 1, .9, 'interoception'), world: mk(world, observation.worldContext?.uncertainty == null ? .7 : .9, .75, 'world'), social: mk(social, observation.socialSignal == null ? .35 : 1, .6, 'social'), context: mk(context, 1, .8, 'context') } };
};
