    recordPrediction(input: {
        tick: number;
        kind: 'reward' | 'self' | 'world';
        action: string;
        predicted01: number;
        confidence01: number;
        context?: Record<string, unknown>;
    }): string { const id = this.evidenceResearchSubsystem.predictionLedger.record({ ...input, at: Date.now() }); const horizon = input.kind === 'world' ? 12 : input.kind === 'self' ? 4 : 1; const priority = clamp(input.confidence01 * .55 + input.predicted01 * .2 + (input.kind === 'world' ? .25 : .1)); this.evidenceResearchSubsystem.predictionDebt.register(id, input.kind, input.tick, input.tick + horizon, priority); if (input.kind === 'world')
        this.worldSubsystem.trackPrediction({ predictionId: id, claimKey: `action:${input.action}`, predicted01: input.predicted01, confidence01: input.confidence01 }); return id; }
    resolvePrediction(id: string, actual01: number): ReturnType<PredictionLedger['resolve']> {
        const r = this.evidenceResearchSubsystem.predictionLedger.resolve(id, actual01);
        if (r) {
            this.evidenceResearchSubsystem.predictionDebt.resolve(id, r.resolvedAt ? r.tick : this.persisted.state.tick);
            this.persistence.continuity.frames += 1;
            this.persistence.continuity.lastAt = Date.now();
            this.persistence.continuity.lastTick = r.tick;
            this.persistence.continuity.lastJointError01 = r.error01 ?? 0.5;
            this.persistence.continuity.meanJointError01 = clamp(this.persistence.continuity.meanJointError01 * 0.92 + (r.error01 ?? 0.5) * 0.08);
            this.persisted.system.predictionLedger = this.evidenceResearchSubsystem.predictionLedger.snapshot();
            this.persisted.system.predictionDebt = this.evidenceResearchSubsystem.predictionDebt.snapshot();
            this.persisted.system.continuity = { ...this.persistence.continuity };
        }
        return r;
    }
