    autonomousProjectExecutionStatusSnapshot() {
        const state = this.agencySubsystem.projectExecutor.snapshot();
        const tick = Math.max(0, Math.floor(Number(this.persisted.state.tick) || 0));
        const health = this.agencySubsystem.projectExecutor.planHealth(tick);
        const steps = state.steps.map((step) => {
            const dependenciesReady = (step.dependsOn ?? []).every((id) => state.steps.find((candidate) => candidate.id === id)?.completed === true);
            const waitingForRetry = step.retryAfterTick != null && step.retryAfterTick > tick;
            const status = step.completed ? 'completed' : step.blocked ? 'blocked' : !dependenciesReady ? 'waiting-dependency' : waitingForRetry ? 'waiting-retry' : state.steps[state.cursor]?.id === step.id ? 'current' : 'queued';
            return {
                id: step.id, action: step.action, preferredTool: step.preferredTool ?? null, purpose: step.purpose,
                dependsOn: [...(step.dependsOn ?? [])], status,
                requiredEvidence01: clamp(step.requiredEvidence01), expectedProgress01: clamp(step.expectedProgress01),
                attempts: Math.max(0, Math.floor(Number(step.attempts) || 0)),
                successes: Math.max(0, Math.floor(Number(step.successes) || 0)),
                qualifyingAttempts: Math.max(0, Math.floor(Number(step.qualifyingAttempts) || 0)),
                minAttemptsBeforePromotion: Math.max(1, Math.floor(Number(step.minAttemptsBeforePromotion) || 1)),
                failureAttempts: Math.max(0, Math.floor(Number(step.failureAttempts) || 0)),
                maxAttempts: Math.max(1, Math.floor(Number(step.maxAttempts) || 4)),
                retryAfterTick: step.retryAfterTick ?? null,
                lastFailureReason: step.lastFailureReason ?? null,
                requiresExternalResearch: Boolean(step.requiresExternalResearch),
                requiresResearchPromotion: Boolean(step.requiresResearchPromotion || step.requiresPriorResearchPromotion),
            };
        });
        return {
            projectId: state.projectId, tick, planRevision: state.planRevision, cursor: state.cursor,
            progress01: this.agencySubsystem.projectExecutor.progress01(), health,
            completedSteps: state.completedSteps, totalSteps: state.steps.length, validatedSteps: state.validatedSteps,
            executionScore01: state.executionScore01, skillPromotionCandidate01: state.skillPromotionCandidate01,
            toolCalls: state.toolCalls, toolSuccesses: state.toolSuccesses, blockedCycles: state.blockedCycles,
            lastOutcome: state.lastOutcomeId ? { id: state.lastOutcomeId, verified: state.lastOutcomeVerified } : null,
            activeOperation: state.activeOperation ? {
                projectId: state.activeOperation.projectId,
                stepId: state.activeOperation.stepId,
                toolId: state.activeOperation.toolId,
                stage: state.activeOperation.stage,
                executionId: state.activeOperation.executionId ?? null,
                outcomeClass: state.activeOperation.outcomeClass ?? null,
                approvalRequestId: state.activeOperation.approvalRequestId ?? null,
                updatedAt: state.activeOperation.updatedAt,
                // Operation keys and request fingerprints are deliberately not exposed to the UI.
            } : null,
            steps,
            note: state.activeOperation
              ? 'A durable step operation is active. Pending/ambiguous operations must be reconciled before a different request can execute.'
              : 'A step advances only after its required tool binding, evidence threshold, research gates, and qualifying-attempt policy all pass.'
        };
    }
