    recordSemanticVisionFrame() { this.embodimentSubsystem.cameraEvidence.state.semanticFrames++; this.embodimentSubsystem.cameraEvidence.state.semanticVisionAvailable = true; this.persisted.facets.embodiment.cameraEvidence = this.embodimentSubsystem.cameraEvidence.snapshot(); }
    recordCameraEvidence(evidence: CameraEvidence) {
        const priorHash = this.embodimentSubsystem.cameraEvidence.state.last?.sha256 ?? '';
        const normalized = { ...evidence, novelty01: evidence.sha256 && evidence.sha256 === priorHash ? 0 : evidence.novelty01 };
        this.embodimentSubsystem.cameraEvidence.record(normalized);
        this.persisted.facets.embodiment.cameraEvidence = this.embodimentSubsystem.cameraEvidence.snapshot();
        this.persisted.facets.embodiment.deviceEvidence = this.cognitiveRuntime.deviceEvidence.snapshot();
        const confidence = clamp(normalized.captureQuality01 * .72 + .08);
        this.recordMultimodalObservation({ modality: 'vision', summary: `camera-capture:${normalized.width ?? '?'}x${normalized.height ?? '?'}:${normalized.byteLength}B:novelty=${normalized.novelty01.toFixed(2)}`, confidence, salience: clamp(.35 + normalized.novelty01 * .5), evidence: ['android-camera', 'camera-evidence-processor'], content: normalized.sha256 || `camera:${normalized.at}:${normalized.byteLength}` });
        const feature = [clamp((normalized.width ?? 320) / 1920), clamp((normalized.height ?? 240) / 1080), normalized.byteEntropy01, normalized.novelty01, normalized.captureQuality01, clamp(normalized.byteLength / 1000000)];
        this.p41NativeIngest({ vision: { features: feature, width: normalized.width ?? 320, height: normalized.height ?? 240 }, at: normalized.at });
        // Acquisition is not semantic understanding. Keep the unresolved vision query explicit
        // until a declared backend actually returns semantic scene/object evidence.
        this.p41PerceptionIngest({ vision: { sceneLabel: undefined, confidence01: 0, objects: [], relations: [], events: [], latencyMs: 0, semantic: false }, at: normalized.at });
        const semantic = this.p41PerceptionSnapshot();
        if (semantic.pending.some(p => p.modality === 'vision' && p.status === 'pending'))
            this.embodimentSubsystem.cameraEvidence.state.unresolvedSemanticRequests = semantic.pending.filter(p => p.modality === 'vision' && p.status === 'pending').length;
        return structuredClone(this.embodimentSubsystem.cameraEvidence.state);
    }
