    b268RunPolicyExperiment(spec: B268ExperimentSpec, families: Parameters<typeof evaluateB264SnapshotOnFamilies>[2], tick = this.persisted.state.tick) {
        const baselineSnapshot = this.developmentalNeural.causalPolicyLearningB264.snapshot();
        const trialSnapshot = mutateB264PolicySnapshot(baselineSnapshot, spec);
        const baseline = evaluateB264SnapshotOnFamilies(baselineSnapshot, this.developmentalNeural.realActionCausalityB263, families, this.persisted.state, tick + 1000);
        const trial = evaluateB264SnapshotOnFamilies(trialSnapshot, this.developmentalNeural.realActionCausalityB263, families, this.persisted.state, tick + 2000);
        const result = this.developmentalNeural.causalSelfExperimentLabB268.evaluate(spec, baseline, trial, tick);
        if (result.decision === 'commit') {
            this.developmentalNeural.causalPolicyLearningB264.restore(trialSnapshot);
        }
        else {
            this.developmentalNeural.causalPolicyLearningB264.restore(baselineSnapshot);
        }
        this.persisted.system.causalPolicyLearningB264 = this.developmentalNeural.causalPolicyLearningB264.snapshot();
        this.persisted.system.causalSelfExperimentLabB268 = this.developmentalNeural.causalSelfExperimentLabB268.snapshot();
        return { ...result, baseline, trial, committed: result.decision === 'commit' };
    }
