    private buildAutonomousCognitiveLifeContext(state: OrganismState, observation: any, n: any, socialPredictionError: number): AutonomousCognitiveLifeContext {
        const lifeSummary = this.developmentalNeural.lifeCourseNavigator.snapshot();
        const curriculum = this.developmentalNeural.personalCurriculum.snapshot();
        const portfolio = this.developmentalNeural.developmentalPortfolio.snapshot();
        const executive = this.developmentalNeural.developmentalExecutive.snapshot();
        const executiveProject = executive.projects.find((x: any) => x.id === executive.activeProjectId);
        const future = this.cognitiveRuntime.futureSelf.snapshot();
        const synthesis = this.developmentalNeural.developmentalSynthesis.diagnostics();
        const evidence = this.persisted.facets.consciousness.consciousnessEvidence;
        return {
            state, goals: this.persisted.goals, activeGoalId: this.persisted.goals.find(g => g.status === 'active')?.id ?? null,
            self01: clamp(this.persisted.facets.consciousness.identityContinuity.continuity),
            identityDrift01: clamp(1 - this.persisted.facets.consciousness.identityContinuity.continuity),
            autobiographical01: clamp(this.selfSubsystem.p84AutobiographicalContinuity.summary().causalContinuity01 ?? .5),
            relational01: clamp(this.config.enableSocialDevelopment ? (this.cognitiveRuntime.socialDevelopment.summary().user?.trust ?? .5) : .5),
            social01: clamp(n.socialNeed), socialError01: clamp(socialPredictionError ?? 0),
            goalPressure01: clamp(state.needs.goalPressure), uncertainty01: clamp(n.uncertainty),
            predictionError01: clamp(state.predictionError), selfPredictionError01: clamp(state.selfPredictionError), novelty01: clamp(n.novelty),
            energy01: clamp(state.needs.energy), capacity01: clamp(1 - state.needs.cognitiveLoad),
            thermal01: clamp((state.needs as any).thermalStrain ?? observation.embodiment?.thermalStrain01 ?? 0),
            sensoryFreshness01: clamp(observation.embodiment?.sensoryFreshness01 ?? .6),
            transfer01: clamp(synthesis.abstraction01), retention01: clamp(executiveProject?.retention01 ?? .5),
            curriculumPressure01: clamp(curriculum.curriculumPressure01), futureMismatch01: clamp(future.lastDevelopmentalMismatch01),
            futureIdentityCoherence01: clamp(future.futureIdentityCoherence ?? .5), regret01: clamp(this.persisted.facets.advanced.regret?.meanRegret ?? 0),
            counterfactualGap01: clamp(synthesis.counterfactualRegret01 ?? .2),
            evidence01: clamp(evidence.aggregateCausalEvidence * .5 + evidence.aggregateLongitudinalEvidence * .3 + evidence.aggregateCoverage * .2),
            resource01: clamp(portfolio.allocation01 ? 1 - portfolio.competition01 * .35 : state.needs.energy),
            commitmentCount: lifeSummary.continuityDebt01 > 0 ? 1 : 0, unfinishedIntentions: 0, socialPeople: 1, worldEntities: 0, contextKey: `tick:${state.tick}`, at: state.at
        };
    }
