        if (reflection.compacted > 0)
            this.memorySubsystem.events.append(makeEvent('memory-created', this.persisted.state.tick, { source: 'p47-temporal-memory', compacted: reflection.compacted, openContradictions: reflection.openContradictions }));
        const replayUpdatesP23 = this.developmentalNeural.p23Learning.replayPending(this.persisted.traces, this.cognitiveRuntime.adaptivePolicy);
        const replayUpdates = replayUpdatesP23;
        const memoryPromotions = this.cognitiveRuntime.longitudinal.consolidateMemory({ items: this.memorySubsystem.memoryOS.snapshot().items.map(i => ({ id: i.id, epistemicStatus: i.epistemicStatus, confidence: i.confidence, source: i.source, entities: i.entities, semanticLinks: i.semanticLinks, predictionError: i.predictionError })) });
        this.memorySubsystem.memoryLifecycleAuthority.maintainCanonical({ tick: this.persisted.state.tick, pressure01: .5, maxItems: 1600 });
        this.persisted.facets.learning.adaptivePolicy = this.cognitiveRuntime.adaptivePolicy.snapshot();
        this.persisted.facets.learning.p23 = this.developmentalNeural.p23Learning.snapshot();
        this.persisted.facets.cognition.contextualWorld = this.worldSubsystem.contextualWorld.snapshot();
        this.persisted.facets.learning.p26 = this.developmentalNeural.p26TrueLearning.snapshot();
        this.persisted.facets.learning.p28 = this.developmentalNeural.p28Plasticity.snapshot();
        this.persisted.facets.learning.p29 = this.developmentalNeural.p29Learning.snapshot();
        this.persisted.facets.cognition.p27 = this.worldSubsystem.p27NeuralWorld.snapshot();
        (this.persisted.facets.cognition as any).brainSubstrate = this.worldSubsystem.brainSubstrate.snapshot();
        this.persisted.facets.cognition.centralBrain = this.cognitiveRuntime.centralBrain.snapshot();
        this.persisted.facets.cognition.predictiveSelfAgency = this.cognitiveRuntime.predictiveSelfAgency.snapshot();
        this.persisted.facets.cognition.globalWorkspace = this.cognitiveRuntime.globalWorkspace.snapshot();
        (this.persisted.facets.cognition as any).metacognitiveNeural = this.cognitiveRuntime.metacognitiveNeural.snapshot();
        (this.persisted.facets.advanced as any).predictiveAllostasis = this.cognitiveRuntime.predictiveAllostasis.snapshot();
        (this.persisted.facets.advanced as any).multiHorizonAllostasis = this.cognitiveRuntime.multiHorizonAllostasis.snapshot();
        (this.persisted.facets.advanced as any).neuromodulatoryPlasticity = this.cognitiveRuntime.neuromodulatoryPlasticity.snapshot();
        this.persisted.facets.advanced.memoryFabric = this.memorySubsystem.fabric.snapshot();
        this.persisted.facets.advanced.memoryLifecycleAuthority = this.memorySubsystem.memoryLifecycleAuthority.snapshot();
        this.persisted.facets.advanced.memoryOS = this.memorySubsystem.memoryOS.snapshot();
        this.cognitiveRuntime.longitudinal.evaluate(this.worldSubsystem.worldModel2.snapshot(), this.worldSubsystem.worldModel2.calibrationError(), this.persisted.traces, this.selfSubsystem.identityContinuity.snapshot().continuity);
        this.persisted.facets.advanced.longitudinal = this.cognitiveRuntime.longitudinal.snapshot();
        return { replayUpdates, memoryPromotions, health: this.cognitiveRuntime.longitudinal.snapshot() };
