                    const event = makeEvent('external-outcome-verified', this.persisted.state.tick, { tool: input.tool ?? 'unknown', executionId: input.actionRef, observationId: observation.id, confidence01: assessment.confidence01, recommendedConfidence01: reconciliation.recommendedConfidence01, consensusStatus: reconciliation.status, expectedPostcondition: assessment.expectedPostcondition, observedPostcondition: assessment.observedPostcondition, source: observation.sourceId } as any, observation.observedAt);
